<script setup>
import SystemChecks from './SystemChecks.vue'
import OptionalModules from './OptionalModules.vue'
import ApplicationContext from './ApplicationContext.vue'
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, errorMessage, localTime } from './api'
import { duration } from './employee-utils'
import './employee.css'
import EmployeeProfile from './EmployeeProfile.vue'
import MyData from './MyData.vue'
import WorkPerformance from './WorkPerformance.vue'

const state = ref(null), error = ref(''), message = ref(''), busy = ref(false), saving = ref(false), accepted = ref(false)
const connection = reactive({server_url:'', device_name:''}), credentials = reactive({email:'', password:''})
const profile = reactive({phone:'', location:'', timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'})
const leave = reactive({type:'annual', start_date:'', end_date:'', reason:''})
const tab = ref('Overview'), portal = ref(null), portalError = ref(''), portalBusy = ref(false), historyPage = ref(1)
const clock = ref(new Date()), connectionLoaded = ref(false)
const navigation = ['Overview', 'My time', 'Login history', 'Work & goals', 'Leave requests', 'My data', 'Videos', 'Activity reviews', 'My profile', 'Device settings', 'System checks']
const configured = computed(()=>!!state.value?.server_url && connection.server_url === state.value.server_url && connection.device_name === state.value.device_name)
const today = computed(()=>portal.value?.daily?.[0]?.active_seconds ?? 0)
const week = computed(()=>portal.value?.daily?.slice(0,7).reduce((sum,d)=>sum+(d.active_seconds ?? 0),0) ?? 0)
const chart = computed(()=>[...(portal.value?.daily?.slice(0,7) ?? [])].reverse())
const chartMax = computed(()=>Math.max(3600,...chart.value.map(d=>(d.active_seconds ?? 0))))
const pendingLeaves = computed(()=>portal.value?.pending_leave_count ?? portal.value?.leaves?.filter(l=>l.status==='pending').length ?? 0)
const firstName = computed(()=>state.value?.user?.name?.split(' ')[0] || 'there')
let statusTimer, clockTimer, portalTimer, owner = null, generation = 0, profileLoaded = false
function resetPortal(){generation++;portal.value=null;portalError.value='';portalBusy.value=false;profileLoaded=false;historyPage.value=1;tab.value='Overview';Object.assign(profile,{phone:'',location:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'});Object.assign(leave,{type:'annual',start_date:'',end_date:'',reason:''})}
async function refresh(){try{const next=(await api.get('/local/status')).data;state.value=next;if(!connectionLoaded.value){Object.assign(connection,{server_url:next.server_url,device_name:next.device_name});connectionLoaded.value=true}const id=next.user?.id ?? null;if(id!==owner){owner=id;resetPortal();if(id)loadPortal()}}catch(err){error.value='Cannot reach the local agent. '+errorMessage(err)}}
// A save must refresh even during polling. Only the latest request may publish its result.
async function loadPortal(){if(!owner)return;const current=++generation;portalBusy.value=true;try{const {data}=await api.get('/local/portal',{params:{timezone:profile.timezone,page:historyPage.value}});if(current!==generation)return;portal.value=data;portalError.value='';if(!profileLoaded){Object.assign(profile,{phone:data.profile.phone,location:data.profile.location,timezone:data.profile.timezone});profileLoaded=true}}catch(err){if(current===generation)portalError.value=errorMessage(err)}finally{if(current===generation)portalBusy.value=false}}
async function saveConnection(){saving.value=true;error.value='';message.value='';try{await api.post('/local/config',connection);connectionLoaded.value=false;await refresh();accepted.value=false;message.value='Connection verified. Your settings are saved.'}catch(err){error.value=errorMessage(err)}finally{saving.value=false}}
async function login(){busy.value=true;error.value='';message.value='';try{await api.post('/local/login',{...credentials,notice_accepted:accepted.value});credentials.password='';await refresh()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function logout(){busy.value=true;try{await api.post('/local/logout');owner=null;resetPortal();message.value='You are signed out. Capture has stopped.';await refresh()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function saveProfile(){busy.value=true;message.value='';error.value='';try{await api.post('/local/profile',profile);message.value='Profile updated.';await loadPortal()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function submitLeave(){busy.value=true;error.value='';message.value='';try{await api.post('/local/leave',leave);Object.assign(leave,{type:'annual',start_date:'',end_date:'',reason:''});message.value='Your leave request was sent for approval.';await loadPortal()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function cancelLeave(id){busy.value=true;error.value='';try{await api.post('/local/leave-cancel',{id});message.value='Leave request cancelled.';await loadPortal()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function history(delta){historyPage.value+=delta;await loadPortal()}
function sessionLabel(session){if(session.end_reason)return session.end_reason.replaceAll('_',' ');return Date.now()-new Date(session.last_seen_at).getTime()>60000?'No recent connection':'Connected'}
function dayLabel(date){return new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'})}
onMounted(()=>{refresh();statusTimer=setInterval(refresh,3000);clockTimer=setInterval(()=>clock.value=new Date(),1000);portalTimer=setInterval(loadPortal,30000)})
onUnmounted(()=>{generation++;clearInterval(statusTimer);clearInterval(clockTimer);clearInterval(portalTimer)})
const idleReminder = computed(()=>state.value?.tracking && state.value?.policy?.idle_alert_minutes > 0 && state.value?.presence?.idle_seconds >= state.value.policy.idle_alert_minutes*60)
async function acceptModules(){busy.value=true;error.value='';try{await api.post('/local/modules-consent',{accepted:true,policy_version:state.value.policy.version});message.value='Acknowledgment saved. Optional modules update on the next heartbeat.';await refresh()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>

<template>
<div class="employee-app" :class="{'employee-signed-out':!state?.user}">
  <aside v-if="state?.user" class="employee-sidebar">
    <div class="brand"><span class="brand-symbol">a</span>activity<span class="brand-dot">.</span></div>
    <div class="employee-workspace-label">YOUR WORKSPACE</div>
    <nav aria-label="Employee navigation"><button v-for="(item,index) in navigation" :key="item" :class="{active:tab===item}" @click="tab=item;message='';error=''" :aria-current="tab===item?'page':undefined"><span class="employee-nav-number">0{{index+1}}</span>{{item}}<span v-if="item==='Leave requests' && pendingLeaves" class="employee-count">{{pendingLeaves}}</span></button></nav>
    <div class="employee-sidebar-note"><span class="employee-live-dot" :class="{on:state.tracking && state.presence?.state === 'active'}"></span><strong>{{state.tracking?(state.presence?.state === 'active'?'Capture active':'Screenshots paused'):'Capture stopped'}}</strong><p>You can see what is collected, review your time and manage your requests.</p></div>
    <div class="employee-account"><div class="employee-avatar">{{state.user.name.slice(0,1).toUpperCase()}}</div><div><strong>{{state.user.name}}</strong><small>Employee workspace</small></div><button @click="logout" :disabled="busy" title="Sign out and stop capture" aria-label="Sign out">↗</button></div>
  </aside>
  <div class="employee-body">
    <header class="employee-topbar"><div v-if="state?.user"><span class="muted">Workspace / </span>{{tab}}</div><div v-else class="brand dark"><span class="brand-symbol">a</span>activity<span class="brand-dot">.</span></div><div class="employee-clock">{{clock.toLocaleDateString(undefined,{month:'short',day:'numeric'})}}<span>{{clock.toLocaleTimeString()}}</span></div></header>
    <main class="employee-content">
      <div v-if="!state" class="card"><template v-if="error"><p role="alert" class="notice danger">{{error}}</p><p>Reload this page to reconnect. If the problem continues, close and restart the desktop agent.</p><button @click="refresh">Retry connection</button></template><template v-else>Connecting to your local agent…</template></div>
      <template v-else>
      <div v-if="error" role="alert" class="notice danger">{{error}}</div><div v-if="message" role="status" class="notice success">{{message}}</div>
      <details v-if="!state.user"><summary>System requirements & checks</summary><SystemChecks :agent="true" /></details><SystemChecks v-if="state.user && tab === 'System checks'" :agent="true" /><div v-if="!state.user" class="employee-welcome-grid">
        <section class="employee-welcome"><div class="eyebrow">YOUR WORKDAY, IN ONE PLACE</div><h1>A little clarity.<br>A better workday.</h1><p>Connect your workstation to see your tracked time, review captures and keep everyday HR requests in one place.</p><div class="employee-welcome-points"><div><b>01</b><span>Connect your company's server</span></div><div><b>02</b><span>Sign in with your employee account</span></div><div><b>03</b><span>See your workday as it happens</span></div></div><div class="employee-transparent"><strong>Visible by design</strong><p>Screen and app capture starts after sign-in. The tray icon and this window keep its status visible.</p></div></section>
        <div><section class="card"><div class="eyebrow">STEP 01 · CONNECTION</div><h2>Your workstation</h2><form @submit.prevent="saveConnection"><label>Company server address<input v-model.trim="connection.server_url" type="url" placeholder="https://ourteam.test" required :disabled="saving || busy"></label><label>Device name<input v-model.trim="connection.device_name" maxlength="120" placeholder="My workstation" required :disabled="saving || busy"></label><button class="full" :disabled="saving || busy">{{saving?'Checking connection…':'Save & connect'}}</button></form></section>
        <section class="card"><div class="eyebrow">STEP 02 · YOUR ACCOUNT</div><h2>Welcome back</h2><p v-if="!configured" class="muted">Save your connection settings above to continue.</p><form @submit.prevent="login"><label>Work email<input v-model.trim="credentials.email" type="email" autocomplete="username" required></label><label>Password<input v-model="credentials.password" type="password" autocomplete="current-password" required></label><div class="monitoring-notice"><strong>Capture notice</strong><p>{{state.notice}}</p></div><label class="check-label"><input v-model="accepted" type="checkbox" required>I have read the capture notice.</label><button class="primary full" :disabled="busy || saving || !accepted || !configured">{{busy?'Signing in…':'Sign in to my workspace →'}}</button><p class="employee-form-footnote">Your session is protected by Windows. Your password is never saved.</p></form></section></div>
      </div>
      <template v-else>
        <div class="employee-heading"><div><div class="eyebrow">EMPLOYEE WORKSPACE</div><h1>{{tab==='Overview'?`Good to see you, ${firstName}.`:tab}}</h1><p class="muted">{{tab==='Overview'?'Your day, your time, your peace of mind.':state.device_name+' · '+state.user.email}}</p></div><span class="pill" :class="state.tracking && state.presence?.state === 'active'?'green':'neutral'">{{state.tracking?(state.presence?.state === 'active'?'● Capture active':'● Screenshots paused'):'Capture stopped'}}</span></div>
        <section v-if="state?.user && (state.policy.video_enabled || state.policy.anomaly_enabled)" class="card"><h2>Optional recording & activity review</h2><p>{{state.policy.modules_notice}}</p><p v-if="state.video_recording" class="notice danger" role="status">● RECORDING SCREEN VIDEO</p><p v-else-if="state.policy.video_enabled" role="status">{{state.video_message || 'Video paused or waiting for the next clip.'}}</p><button v-if="!state.policy.modules_consented" :disabled="busy" @click="acceptModules">I have read this notice — enable the described modules</button><p v-else>Optional-module notice acknowledged. Sign out to stop capture.</p></section><OptionalModules v-if="['Videos','Activity reviews'].includes(tab) && state?.user" :kind="tab==='Videos'?'videos':'anomalies'" /><p v-if="idleReminder" class="notice" role="status">No keyboard or mouse input for {{Math.floor(state.presence.idle_seconds/60)}} minutes. Screenshots pause at your configured idle threshold. Reading, meetings and calls can also appear idle.</p><ApplicationContext v-if="tab === 'My time'" :context="portal?.application_context" />
<div v-if="portalError" class="notice danger" role="alert">{{portalError}} <button class="small-button" :disabled="portalBusy" @click="loadPortal">Retry</button></div>
        <p v-if="portalBusy && !portal" class="muted" role="status">Loading your employee records…</p>
        <template v-if="tab==='Overview'">
          <div class="employee-metrics"><article class="employee-metric featured"><span>Computer engagement today</span><strong>{{portal?duration(today):'—'}}</strong><small>Input activity, not productivity · {{portal?.profile.timezone || 'Waiting for server'}}</small></article><article class="employee-metric"><span>Last 7 days</span><strong>{{portal?duration(week):'—'}}</strong><small>Estimated active time</small></article><article class="employee-metric"><span>Pending requests</span><strong>{{portal?pendingLeaves:'—'}}</strong><small>Waiting for HR review</small></article><article class="employee-metric"><span>Upload queue</span><strong>{{state.pending}}</strong><small>{{state.queue_mb}} MB on this device</small></article></div>
          <div class="employee-overview-grid"><section class="card"><div class="card-heading"><div><h2>Your week at a glance</h2><small>Tracked time · last 7 days</small></div><button class="text-button" @click="tab='My time'">View details →</button></div><div v-if="chart.length" class="employee-chart" role="img" aria-label="Daily tracked time for the last seven days"><div v-for="day in chart" :key="day.date" class="employee-chart-column"><span>{{duration((day.active_seconds ?? 0))}}</span><div class="employee-bar-space"><div class="employee-bar" :style="{height:Math.max(2,(day.active_seconds ?? 0)/chartMax*100)+'%'}" :title="day.date+': '+duration((day.active_seconds ?? 0))"></div></div><small>{{dayLabel(day.date)}}</small></div></div><p v-else class="employee-empty">Time records will appear after the server confirms your connection.</p><p class="employee-caption">Active time uses keyboard/mouse timestamps with a {{state.idle_threshold_seconds}}-second idle threshold. Locked, idle and offline time is excluded. Reading and meetings may appear idle; this is not a payroll calculation.</p></section>
          <section class="card employee-status-card"><div class="eyebrow">DEVICE STATUS</div><h2>{{state.device_name}}</h2><p>{{state.message}}</p><dl><div><dt>Activity</dt><dd>{{state.presence?.state || 'unknown'}} · idle after 5 minutes</dd></div><div><dt>Last server contact</dt><dd>{{localTime(state.last_contact)}}</dd></div><div><dt>Screenshot interval</dt><dd>{{state.policy.screenshot_interval_seconds}} seconds · random</dd></div><div><dt>Browser addresses</dt><dd>{{state.policy.browser_urls?'Enabled where supported':'Disabled'}}</dd></div></dl></section></div>
          <section class="card"><div class="card-heading"><div><h2>Your latest screenshot upload</h2><small>The same capture sent to your organization</small></div><span class="pill neutral">Visible to you</span></div><div v-if="state.screenshot_preview" class="employee-capture"><a :href="`/local/screenshot-preview?id=${encodeURIComponent(state.screenshot_preview.id)}`" target="_blank" rel="noopener"><img :src="`/local/screenshot-preview?id=${encodeURIComponent(state.screenshot_preview.id)}`" alt="Latest screenshot uploaded by this workstation"></a><div><span class="eyebrow">LATEST UPLOAD</span><h3>{{state.screenshot_preview.state}}</h3><p>{{localTime(state.screenshot_preview.captured_at)}}</p><p class="muted">Select the preview to open the full image.</p></div></div><p v-else class="employee-empty">Your screenshot preview appears here when an upload starts.</p><p v-if="state.failed_uploads" class="notice danger">{{state.failed_uploads}} uploads need administrator inspection.</p><p class="employee-caption">{{state.upload_message}} · {{state.capture_message}}</p></section>
        </template>
        <WorkPerformance v-if="tab==='Work & goals'" />
        <section v-if="tab==='My time'" class="card"><div class="card-heading"><div><h2>Daily working hours</h2><small>Last 30 days · {{portal?.profile.timezone}} · Updated {{localTime(portal?.as_of)}}</small></div><button :disabled="portalBusy" @click="loadPortal">Refresh</button></div><p class="employee-caption">Server-confirmed estimates, updated about every 30 seconds. State transitions and gaps over one minute are excluded. Overlapping devices count once, with active time taking priority. Earlier records have no idle detection and appear under Legacy.</p><div class="table-scroll"><table><thead><tr><th>Date</th><th>Active</th><th>Idle</th><th>Legacy</th><th>Daily total</th></tr></thead><tbody><tr v-for="day in portal?.daily || []" :key="day.date"><td>{{day.date}}</td><td><strong>{{duration((day.active_seconds ?? 0))}}</strong></td><td>{{duration(day.idle_seconds ?? 0)}}</td><td>{{duration(day.legacy_seconds ?? 0)}}</td><td><div class="employee-time-track"><div :style="{width:Math.min(100,(day.active_seconds ?? 0)/86400*100)+'%'}"></div></div></td></tr></tbody></table></div></section>
        <section v-if="tab==='Login history'" class="card"><div class="card-heading"><div><h2>Your sign-ins</h2><small>Employee agent sessions across your devices</small></div></div><div class="table-scroll"><table><thead><tr><th>Signed in</th><th>Device</th><th>Last confirmed contact</th><th>Status</th></tr></thead><tbody><tr v-for="session in portal?.sessions.data || []" :key="session.id"><td>{{localTime(session.started_at)}}<small v-if="session.kind==='restored'">Existing session first recorded after upgrade</small></td><td>{{session.device_name}}</td><td>{{localTime(session.ended_at || session.last_seen_at)}}</td><td><span class="pill neutral">{{sessionLabel(session)}}</span></td></tr><tr v-if="portal && !portal.sessions.data.length"><td colspan="4" class="empty-cell">No recorded sessions yet.</td></tr></tbody></table></div><div class="pagination"><span>Page {{portal?.sessions.current_page || 1}} of {{portal?.sessions.last_page || 1}}</span><div><button :disabled="portalBusy || historyPage<=1" @click="history(-1)">Previous</button><button :disabled="portalBusy || !portal || historyPage>=portal.sessions.last_page" @click="history(1)">Next</button></div></div></section>
        <div v-if="tab==='Leave requests'" class="employee-hr-grid"><form class="card" @submit.prevent="submitLeave"><h2>Plan some time away</h2><p class="muted">Submit a request for your administrator to review.</p><label>Leave type<select v-model="leave.type"><option value="annual">Annual leave</option><option value="sick">Sick leave</option><option value="personal">Personal leave</option><option value="unpaid">Unpaid leave</option></select></label><div class="form-grid"><label>First day<input v-model="leave.start_date" type="date" required></label><label>Last day<input v-model="leave.end_date" type="date" :min="leave.start_date" required></label></div><label>Reason<textarea v-model.trim="leave.reason" rows="4" minlength="3" maxlength="2000" required placeholder="A brief note for your administrator"></textarea></label><button class="primary full" :disabled="busy || !portal">Submit leave request</button><p class="employee-form-footnote">Dates are inclusive calendar days. Leave balances and holidays are not calculated.</p></form><section class="card"><h2>Your requests</h2><p v-if="portal && !portal.leaves.length" class="employee-empty">No leave requests yet. Your requests and decisions will appear here.</p><article v-for="item in portal?.leaves || []" :key="item.id" class="employee-leave-item"><div><strong>{{item.type}} leave</strong><span class="pill" :class="item.status==='approved'?'green':item.status==='pending'?'amber':'neutral'">{{item.status}}</span></div><p>{{item.start_date}} → {{item.end_date}}</p><p class="muted employee-reason">{{item.reason}}</p><p v-if="item.review_note" class="monitoring-notice">HR: {{item.review_note}}</p><button v-if="item.status==='pending'" class="text-button" :disabled="busy" @click="cancelLeave(item.id)">Cancel request</button></article><p class="employee-caption">Showing your latest 50 requests.</p></section></div>
        <EmployeeProfile v-if="tab==='My profile'" :record="portal?.profile" @saved="loadPortal" />
        <MyData v-if="tab==='My data'" :timezone="portal?.profile.timezone || profile.timezone" />
        <section v-if="tab==='Device settings'" class="card"><h2>Your connection</h2><dl class="agent-details"><div><dt>Server</dt><dd>{{state.server_url}}</dd></div><div><dt>Device</dt><dd>{{state.device_name}}</dd></div><div><dt>Application sampling</dt><dd>Every {{state.policy.activity_interval_seconds}} seconds</dd></div></dl><div class="monitoring-notice"><strong>Your organization's capture notice</strong><p>{{state.notice}}</p></div><p class="muted">Sign out to change the server address or device name. Capture settings are managed by your administrator.</p><button :disabled="busy" @click="logout">Sign out & change connection</button></section>
      </template>
      <footer class="employee-footer">Activity desktop · Closing this tab does not stop the agent. Sign out or close the agent console to stop capture.</footer>
      </template>
    </main>
  </div>
</div>
</template>



